-- FitVerse Jr. core schema
-- Roles: super_admin (us), host (lists spaces), user (student / parent / school)

create type public.app_role as enum ('super_admin', 'host', 'user');
create type public.user_kind as enum ('student', 'parent', 'school');
create type public.space_status as enum ('pending', 'approved', 'rejected');

-- ---------------------------------------------------------------- profiles
create table public.profiles (
  id uuid primary key references auth.users on delete cascade,
  email text,
  full_name text,
  role public.app_role not null default 'user',
  user_kind public.user_kind,
  phone text,
  city text,
  created_at timestamptz not null default now()
);

create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'super_admin');
$$;

-- New auth user -> profile. Self-signup may only pick host or user; super_admin is granted by SQL.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (id, email, full_name, role, user_kind, phone, city)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name'),
    case when new.raw_user_meta_data->>'role' = 'host' then 'host'::public.app_role else 'user'::public.app_role end,
    case when new.raw_user_meta_data->>'user_kind' in ('student', 'parent', 'school')
      then (new.raw_user_meta_data->>'user_kind')::public.user_kind end,
    new.raw_user_meta_data->>'phone',
    new.raw_user_meta_data->>'city'
  );
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

alter table public.profiles enable row level security;

create policy "profiles: read own or admin" on public.profiles
  for select using (id = auth.uid() or public.is_admin());
create policy "profiles: update own or admin" on public.profiles
  for update using (id = auth.uid() or public.is_admin());

-- Users can't change their own role/email; role changes go through set_user_role().
revoke update on public.profiles from authenticated, anon;
grant update (full_name, user_kind, phone, city) on public.profiles to authenticated;

create or replace function public.set_user_role(target uuid, new_role public.app_role)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'only super admins can change roles'; end if;
  update public.profiles set role = new_role where id = target;
end;
$$;

-- ------------------------------------------------------------------ spaces
create table public.spaces (
  id uuid primary key default gen_random_uuid(),
  host_id uuid not null default auth.uid() references public.profiles on delete cascade,
